&lt;figure&gt;&lt;img data-height=&quot;537&quot; data-mime=&quot;image/jpeg&quot; data-ratio=&quot;1.415270018621974&quot; data-src-m=&quot;https://cimg.cnyes.cool/prod/news/6629279/m/b6a36898fe5e992602d69dfcb3ac51ba.jpg&quot; data-width=&quot;760&quot; src=&quot;https://cimg.cnyes.cool/prod/news/6629279/l/b6a36898fe5e992602d69dfcb3ac51ba.jpg&quot; srcset=&quot;https://cimg.cnyes.cool/prod/news/6629279/l/b6a36898fe5e992602d69dfcb3ac51ba.jpg 1x,https://cimg.cnyes.cool/prod/news/6629279/xl/b6a36898fe5e992602d69dfcb3ac51ba.jpg 2x,https://cimg.cnyes.cool/prod/news/6629279/xxl/b6a36898fe5e992602d69dfcb3ac51ba.jpg 3x&quot;&gt;&lt;/figure&gt;

